styles:
:root{
  --navy:#071b3b;--navy2:#0d2c5f;--blue:#124da8;--electric:#1a73e8;--gold:#d7a72b;
  --red:#a91d2d;--green:#0d7a48;--purple:#5a2d91;--teal:#007d82;--orange:#ef6c00;
  --bg:#f4f7fb;--card:#fff;--ink:#172033;--muted:#667085;--line:#dbe3ef;--soft:#eef3f9;
  --shadow:0 10px 30px rgba(20,39,77,.08);--radius:18px;
}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--ink)}
 button,input,select,textarea{font:inherit}button{cursor:pointer}
 .lf-data-source-note{margin:0 0 10px;padding:8px 10px;border:1px solid #c9d9ea;border-radius:9px;background:#f3f8fd;color:#3d5872;font-size:10px;font-weight:800;line-height:1.35}.lf-data-source-note[data-source="current"]{border-color:#9bcbb1;background:#eefaf3;color:#11643c}.lf-data-source-note[data-source="analyzer"]{border-color:#c8b57a;background:#fff9e8;color:#715700}.lf-data-source-note[data-source="none"]{border-color:#e3b2b2;background:#fff4f4;color:#8b2929}
body.dark{--bg:#07111f;--card:#0d1a2b;--ink:#e8eef7;--muted:#9aa9bd;--line:#203249;--soft:#12243a;--shadow:0 10px 30px rgba(0,0,0,.22)}
body.compact .data-table th,body.compact .data-table td{padding:7px 9px;font-size:12px}
[hidden]{display:none!important}
.login-gate{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 20% 0%,#163f82 0,#071b3b 44%,#030b17 100%)}
.login-card{width:min(520px,100%);background:#fff;color:#172033;padding:28px;border-radius:24px;box-shadow:0 30px 90px rgba(0,0,0,.35);display:grid;gap:16px}
.login-brand{display:flex;gap:16px;align-items:center}.login-brand img{width:72px;height:72px;object-fit:contain}.login-brand strong{display:block;font-size:24px;color:var(--navy)}.login-brand span{color:#667085}
.login-card label,.form-stack label{display:grid;gap:6px;font-weight:700;font-size:13px}.login-card input,.login-card select,.form-stack input,.form-stack select,.form-stack textarea,.control-select select,.toolbar input,.toolbar select,.top-actions select{border:1px solid #cfd8e6;border-radius:10px;padding:11px 12px;background:#fff;color:#172033;outline:none}
.warning-strip{padding:10px 12px;border-radius:10px;background:#fff3cd;color:#6b4b00;font-size:12px;font-weight:800;border:1px solid #f1d37b}
.app-shell{min-height:100vh;display:grid;grid-template-columns:260px 1fr}
.sidebar{position:sticky;top:0;height:100vh;background:linear-gradient(180deg,var(--navy),#061126);color:#fff;padding:18px 14px;display:flex;flex-direction:column;z-index:50}
.brand{display:flex;align-items:center;gap:12px;padding:8px 10px 24px;border-bottom:1px solid rgba(255,255,255,.12)}.brand img{width:54px;height:54px;object-fit:contain;background:#fff;border-radius:12px;padding:4px}.brand strong{display:block;font-size:18px;letter-spacing:.08em}.brand span{font-size:11px;color:#b8cae9}
nav{display:grid;gap:7px;margin-top:18px}#nav{min-height:0;overflow-y:auto;overflow-x:hidden;padding-right:3px;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.24) transparent}#nav::-webkit-scrollbar{width:6px}#nav::-webkit-scrollbar-thumb{background:rgba(255,255,255,.22);border-radius:999px}.brand,.sidebar-menu-label,.sidebar-foot{flex-shrink:0}.nav-item{border:0;background:transparent;color:#c7d6ed;padding:12px 14px;border-radius:12px;text-align:left;font-weight:700;display:flex;gap:12px;align-items:center}.nav-item:hover,.nav-item.active{background:rgba(255,255,255,.1);color:#fff}.nav-item.active{box-shadow:inset 3px 0 0 var(--gold)}
.sidebar-menu-label{margin:16px 12px 4px;color:#7794bd;font-size:9px;font-weight:1000;letter-spacing:.16em;text-transform:uppercase}
.nav-item.dispatch-loadflow{border:1px solid rgba(255,255,255,.09);background:linear-gradient(90deg,rgba(18,77,168,.18),rgba(255,255,255,.025));position:relative;overflow:hidden}
.nav-item.dispatch-loadflow span{display:grid;place-items:center;min-width:28px;height:28px;border-radius:9px;background:rgba(255,255,255,.1);color:#fff;font-size:10px;font-weight:1000;letter-spacing:.03em}
.nav-item.dispatch-loadflow small{display:block;margin-top:1px;color:#8fa9cd;font-size:8px;font-weight:800}
.nav-item.dispatch-loadflow.active{background:linear-gradient(90deg,rgba(26,115,232,.34),rgba(215,167,43,.10));border-color:rgba(215,167,43,.38)}
.sidebar-foot{margin-top:auto;border-top:1px solid rgba(255,255,255,.12);padding:18px 10px;color:#b8cae9;display:grid;grid-template-columns:auto 1fr;gap:7px 8px;align-items:center}.sidebar-foot small{grid-column:2}.pulse-dot{width:9px;height:9px;border-radius:50%;background:#43d17a;box-shadow:0 0 0 5px rgba(67,209,122,.12)}
main{min-width:0}.topbar{height:78px;background:var(--card);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 26px;position:sticky;top:0;z-index:40}.topbar h1{font-size:21px;margin:0}.topbar p{margin:4px 0 0;color:var(--muted);font-size:12px}.top-actions{display:flex;gap:10px;align-items:center}.top-actions select{max-width:220px;background:var(--card);color:var(--ink);border-color:var(--line)}
.user-pill{display:grid;padding:7px 12px;border:1px solid var(--line);border-radius:999px}.user-pill b{font-size:12px}.user-pill small{font-size:10px;color:var(--muted)}
.mobile-menu{display:none;border:0;background:transparent;color:var(--ink);font-size:22px}
.safety-banner{margin:16px 24px 0;padding:10px 14px;border:1px solid #f0d47a;background:#fff7d9;color:#6a5000;border-radius:12px;font-size:12px}
.view{display:none;padding:22px 24px 36px}.view.active{display:block}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:16px}.kpi{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:18px;box-shadow:var(--shadow)}.kpi span{font-size:12px;color:var(--muted);font-weight:700}.kpi strong{display:block;font-size:28px;margin:8px 0}.kpi small{font-size:10px;font-weight:900;color:var(--muted)}.kpi .ok{color:var(--green)}
.grid{display:grid;gap:16px;margin-bottom:16px}.grid.two{grid-template-columns:1fr 1fr}
.panel{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:18px;min-width:0}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.panel-head h2{font-size:16px;margin:0}.panel-head p{font-size:11px;color:var(--muted);margin:4px 0 0}
.badge{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:9px;font-weight:900;letter-spacing:.06em}.badge.blue{background:#e8f1ff;color:#1451a5}.badge.green{background:#e7f7ef;color:#087044}.badge.amber{background:#fff0cc;color:#8a5a00}.badge.purple{background:#f1e9fb;color:#5a2d91}
.primary,.ghost,.danger,.success,.warning{border-radius:10px;padding:10px 14px;font-weight:800;border:1px solid transparent}.primary{background:var(--blue);color:#fff}.primary:hover{background:#0d3f8d}.ghost{background:var(--card);color:var(--ink);border-color:var(--line)}.danger{background:#b42318;color:#fff}.success{background:#087a45;color:#fff}.warning{background:#d77d00;color:#fff}.small{padding:7px 10px;font-size:11px}.wide{width:100%}
.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.toolbar input,.toolbar select{padding:8px 10px;background:var(--card);color:var(--ink);border-color:var(--line)}
.network-path{display:flex;align-items:center;gap:8px;overflow:auto;padding:8px 0 2px}.node{min-width:130px;padding:12px;border-radius:12px;background:var(--soft);border:1px solid var(--line)}.node small{display:block;color:var(--muted);font-size:9px;font-weight:800;text-transform:uppercase}.node b{display:block;margin-top:5px;font-size:12px}.arrow{color:var(--gold);font-size:22px;font-weight:900}
.snapshot{display:grid;grid-template-columns:1fr 1fr;gap:12px}.snapshot div{padding:12px;background:var(--soft);border-radius:12px}.snapshot span{display:block;font-size:10px;color:var(--muted);font-weight:800}.snapshot b{display:block;margin-top:6px;font-size:12px}
.event-list{display:grid;gap:8px}.event{display:grid;grid-template-columns:90px 130px 1fr;gap:12px;padding:10px 12px;border-radius:10px;background:var(--soft);font-size:11px}.event time{color:var(--muted)}.event b{font-size:10px}.empty{color:var(--muted);text-align:center;padding:30px}
.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px}.data-table{width:100%;border-collapse:collapse;font-size:12px;min-width:760px}.data-table th{position:sticky;top:0;background:var(--navy2);color:#fff;text-align:left;padding:10px;z-index:2}.data-table td{padding:10px;border-bottom:1px solid var(--line);vertical-align:top}.data-table tr:hover td{background:var(--soft)}.band{display:inline-flex;width:24px;height:24px;border-radius:7px;align-items:center;justify-content:center;color:#fff;font-weight:900}.band-A{background:#0b7a4a}.band-B{background:#2363a5}.band-C{background:#b8860b}.band-D{background:#d05a00}.band-E{background:#b42318}.band-none{background:#697586}
.status{display:inline-flex;align-items:center;gap:6px;font-size:10px;font-weight:900}.status::before{content:"";width:8px;height:8px;border-radius:50%}.status-CLOSED::before{background:#10b981}.status-OPEN::before{background:#f59e0b}.status-TRIPPED::before{background:#ef4444}
.bus-panel{margin-top:16px}.bus-diagram{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:14px}.source-box{padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--soft);display:grid;gap:5px;text-align:center}.source-box small{color:var(--muted);font-weight:900}.source-box strong{color:var(--blue);font-size:17px}.bus-line{display:flex;align-items:center}.bus-line span{height:4px;width:48px;background:var(--gold)}.coupler{border:2px solid var(--gold);border-radius:12px;background:var(--card);color:var(--ink);padding:10px 14px;font-size:10px;font-weight:900}.coupler b{color:var(--red)}
.micro-note{font-size:10px;color:var(--muted);line-height:1.6}
.form-stack{display:grid;gap:12px}.meter-list{display:grid;gap:18px}.meter-list div{display:grid;grid-template-columns:120px 1fr 90px;align-items:center;gap:12px;font-size:12px}.meter-list meter{width:100%;height:14px}
.forms-shell{display:grid;grid-template-columns:230px 1fr;gap:16px}.form-picker{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:10px;height:max-content;position:sticky;top:100px}.form-picker button{width:100%;border:0;background:transparent;color:var(--ink);text-align:left;padding:11px;border-radius:9px;font-weight:750;font-size:11px}.form-picker button:hover,.form-picker button.active{background:var(--soft);color:var(--blue)}
.form-workspace{overflow:hidden}.form-canvas{overflow:auto;background:#e8edf4;border-radius:14px;padding:18px;min-height:640px}
.paper{width:min(1080px,100%);margin:auto;background:#fff;color:#111;box-shadow:0 10px 40px rgba(0,0,0,.16);padding:24px;border-radius:4px;--form:#203f91}.paper.landscape{width:min(1320px,100%)}.paper.green{--form:#0b6f3a}.paper.purple{--form:#4d228b}.paper.maroon{--form:#8f1414}.paper.teal{--form:#006c74}.paper.orange{--form:#ef6500}.paper.burgundy{--form:#8e0e22}
.form-header{display:grid;grid-template-columns:100px 1fr 140px;gap:16px;align-items:center;border-bottom:3px solid var(--form);padding-bottom:10px;margin-bottom:12px}.form-header img{width:86px;height:86px;object-fit:contain}.form-header h3{margin:0;text-align:center;color:var(--form);font-size:25px}.form-header p{text-align:center;margin:4px 0 0;font-weight:800}.form-no{text-align:right;font-weight:900;color:var(--form)}
.form-line{display:grid;grid-template-columns:auto 1fr;gap:8px;align-items:center;margin:7px 0;font-size:11px}.form-line label{font-weight:900;color:var(--form)}.paper input,.paper textarea,.paper select{border:0;border-bottom:1px solid #555;padding:5px;background:transparent;color:#111;min-width:0}.paper textarea{border:1px solid #777;width:100%;resize:vertical}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 16px}.section-title{background:var(--form);color:#fff;padding:7px 10px;font-size:11px;font-weight:900;margin:12px 0 8px}.paper-table{width:100%;border-collapse:collapse;font-size:9px}.paper-table th,.paper-table td{border:1px solid #666;padding:5px}.paper-table th{background:var(--form);color:#fff}.paper-table input,.paper-table textarea{width:100%;border:0;padding:3px;min-width:50px}.paper-table .checkcell{text-align:center}.paper-footer{margin-top:12px;border-top:2px solid var(--form);padding-top:7px;font-size:8px;text-align:center;color:var(--form);font-weight:800}.sign-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.sign-box{border:1px solid #777;padding:8px;font-size:9px}.sign-box b{display:block;color:var(--form);margin-bottom:7px}.checkbox-row{display:flex;gap:12px;flex-wrap:wrap;font-size:10px}.checkbox-row label{display:flex;gap:5px;align-items:center}.paper .lined{background:repeating-linear-gradient(to bottom,transparent 0,transparent 26px,#777 27px);min-height:120px}
.hourly-table{min-width:1150px}.hourly-table th{white-space:nowrap}.hourly-table td input{width:58px}
.control-select{display:grid;gap:6px;font-size:12px;font-weight:800}.control-select select{background:var(--card);color:var(--ink);border-color:var(--line)}.control-state{margin:14px 0;padding:20px;background:var(--soft);border-radius:14px;text-align:center}.control-state strong{font-size:28px;display:block}.control-buttons{display:flex;gap:10px;flex-wrap:wrap}.check-list{display:grid;gap:10px}.check-list label{padding:10px;border-radius:10px;background:var(--soft);font-size:12px}.switch-line{display:flex!important;align-items:center;justify-content:space-between;padding:10px;border:1px solid var(--line);border-radius:10px}
dialog{border:0;border-radius:18px;padding:0;box-shadow:0 30px 80px rgba(0,0,0,.3);max-width:480px}.dialog-card{padding:24px;background:var(--card);color:var(--ink)}.dialog-card h3{margin-top:0}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}
@media(max-width:1100px){.kpis{grid-template-columns:1fr 1fr}.grid.two{grid-template-columns:1fr}.forms-shell{grid-template-columns:1fr}.form-picker{position:static;display:flex;overflow:auto}.form-picker button{min-width:170px}.bus-diagram{grid-template-columns:1fr}.bus-line{justify-content:center;transform:rotate(90deg);margin:10px}}
@media(max-width:780px){.app-shell{grid-template-columns:1fr}.sidebar{position:fixed;left:-280px;width:260px;transition:.2s;overflow:hidden}.sidebar.open{left:0}.mobile-menu{display:block}.topbar{padding:0 14px}.top-actions select{display:none}.user-pill{display:none}.view{padding:16px}.safety-banner{margin:12px 16px 0}.kpis{grid-template-columns:1fr}.snapshot{grid-template-columns:1fr}.panel-head{align-items:flex-start;flex-direction:column}.event{grid-template-columns:70px 1fr}.event span{grid-column:1/-1}.form-canvas{padding:8px}.paper{padding:12px}.form-header{grid-template-columns:60px 1fr}.form-header img{width:54px;height:54px}.form-header h3{font-size:16px}.form-no{display:none}.form-grid,.sign-grid{grid-template-columns:1fr}}
@media print{
 body.form-printing{background:#fff!important}
 body.form-printing .sidebar,
 body.form-printing .topbar,
 body.form-printing .safety-banner,
 body.form-printing .form-picker,
 body.form-printing .panel-head,
 body.form-printing .view:not(#view-forms){display:none!important}
 body.form-printing #appShell{display:block!important}
 body.form-printing #view-forms{display:block!important;padding:0!important}
 body.form-printing .form-workspace{border:0!important;box-shadow:none!important;padding:0!important}
 body.form-printing .form-canvas{background:#fff!important;padding:0!important;overflow:visible!important}
 body.form-printing .paper{box-shadow:none!important;width:100%!important;max-width:none!important;margin:0!important}
}


/* Local authentication */
.auth-message{padding:11px 12px;border-radius:10px;font-size:12px;line-height:1.5;border:1px solid #f0c36b;background:#fff7d9;color:#6a5000}
.auth-message.error{border-color:#f3a6a6;background:#fff0f0;color:#8a1c1c}
.auth-message.ok{border-color:#9ed8b8;background:#eefbf4;color:#126b41}
.auth-foot{display:grid;gap:6px;padding-top:4px;color:#667085;font-size:11px;line-height:1.5}
.auth-foot b{color:#071b3b}
.login-card.busy button,.login-card.busy input{opacity:.65;pointer-events:none}
.role-lock{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border-radius:999px;background:var(--soft);font-size:10px;font-weight:900;color:var(--muted)}


/* Plain testing build */
.test-mode-ribbon{
  position:fixed;right:-50px;top:22px;z-index:2000;
  transform:rotate(35deg);background:#d7a72b;color:#071b3b;
  padding:5px 62px;font-size:9px;font-weight:1000;letter-spacing:.08em;
  box-shadow:0 4px 18px rgba(0,0,0,.18);pointer-events:none
}
.scope-chip{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:#eef3f9;color:#0d2c5f;font-size:10px;font-weight:900}
body.dark .scope-chip{background:#12243a;color:#dce8f8}


/* ===== 2026 Premium Operations UI Upgrade ===== */
:root{--royal:#082757;--royal-2:#0b3c85;--royal-3:#1265c8;--premium-gold:#d9a928;--premium-red:#9f1f2e;--ice:#f7faff}
body{background:radial-gradient(circle at 78% -20%,rgba(29,102,199,.12),transparent 33%),radial-gradient(circle at 12% 5%,rgba(217,169,40,.07),transparent 25%),var(--bg)}
.sidebar{background:linear-gradient(180deg,rgba(255,255,255,.04),transparent 28%),linear-gradient(180deg,#061c3d 0%,#041228 52%,#020b18 100%);box-shadow:18px 0 45px rgba(5,25,55,.08)}
.brand{background:linear-gradient(135deg,rgba(255,255,255,.08),rgba(255,255,255,.015));border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:10px 11px 14px}
.nav-item{transition:.2s ease;border:1px solid transparent}.nav-item:hover{transform:translateX(2px);border-color:rgba(255,255,255,.08)}
.nav-item.active{background:linear-gradient(90deg,rgba(26,115,232,.25),rgba(255,255,255,.06));box-shadow:inset 3px 0 0 var(--premium-gold),0 8px 24px rgba(0,0,0,.08)}
.topbar{background:color-mix(in srgb,var(--card) 92%,transparent);backdrop-filter:blur(18px);box-shadow:0 5px 25px rgba(16,39,75,.04)}
.topbar h1{font-size:22px;letter-spacing:-.02em;color:var(--royal)}body.dark .topbar h1{color:#eaf2ff}
.safety-banner{border:1px solid rgba(217,169,40,.45);background:linear-gradient(90deg,#fff9e8,#fff5d1,#fff9e8);box-shadow:0 8px 24px rgba(179,126,0,.05)}
.command-hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1.45fr) minmax(330px,.75fr);gap:22px;align-items:center;margin-bottom:18px;padding:28px 30px;border-radius:24px;color:#fff;background:radial-gradient(circle at 90% 10%,rgba(255,215,82,.26),transparent 22%),linear-gradient(125deg,#061b3d 0%,#0a326f 52%,#0b59a7 100%);border:1px solid rgba(255,255,255,.13);box-shadow:0 22px 55px rgba(7,35,76,.19)}
.command-hero:after{content:"";position:absolute;inset:auto -10% -65% 30%;height:230px;border:1px solid rgba(255,255,255,.13);border-radius:50%;transform:rotate(-7deg)}
.hero-copy,.hero-stats{position:relative;z-index:2}.hero-eyebrow{font-size:10px;font-weight:900;letter-spacing:.14em;color:#ffe29a}
.command-hero h2{font-size:30px;line-height:1.1;margin:9px 0 10px;letter-spacing:-.035em}.command-hero p{max-width:760px;color:#dce9fb;font-size:12px;line-height:1.7;margin:0}
.hero-tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:17px}.hero-tags span{font-size:10px;font-weight:850;padding:7px 10px;border:1px solid rgba(255,255,255,.15);background:rgba(255,255,255,.08);border-radius:999px}
.hero-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px}.hero-stats div{padding:16px;border-radius:15px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.12);backdrop-filter:blur(8px)}
.hero-stats strong{display:block;font-size:26px;color:#ffe49a}.hero-stats span{display:block;font-size:9px;margin-top:4px;color:#e8f1ff;font-weight:800}
.kpi{position:relative;overflow:hidden;border-color:color-mix(in srgb,var(--line) 78%,#a8c6eb);transition:transform .18s ease,box-shadow .18s ease}.kpi:hover{transform:translateY(-2px);box-shadow:0 16px 35px rgba(20,55,100,.11)}.kpi:before{content:"";position:absolute;left:0;top:0;width:4px;height:100%;background:linear-gradient(var(--royal-3),var(--premium-gold))}
.panel{border-color:color-mix(in srgb,var(--line) 83%,#9ebee7);box-shadow:0 12px 34px rgba(26,54,96,.065)}.panel-head h2{color:var(--royal);font-weight:850;letter-spacing:-.012em}body.dark .panel-head h2{color:#eaf2ff}
.data-table th{background:linear-gradient(180deg,#0b356f,#07285a);font-size:10px;letter-spacing:.025em;text-transform:uppercase}.data-table tbody tr:nth-child(even) td{background:color-mix(in srgb,var(--soft) 36%,transparent)}
.reference-card{position:relative;overflow:hidden}.reference-card:after{content:"";position:absolute;width:120px;height:120px;border-radius:50%;right:-50px;top:-55px;background:rgba(20,80,165,.07)}.fault-ref:after{background:rgba(159,31,46,.07)}
