    display:grid;
    gap:5px;
    font-size:10px;
    font-weight:850;
    color:var(--muted);
}

.network-map-search{
    display:grid;
    grid-template-columns:1fr auto;
    gap:8px;
    margin-top:10px;
}

.network-map-layout{
    display:grid;
    grid-template-columns:minmax(0,1fr) 270px;
    gap:14px;
}

#networkGoogleMap{
    min-height:620px;
    border-radius:15px;
    overflow:hidden;
    background:
        radial-gradient(
            circle at 45% 45%,
            #e8f1ff,
            #d9e5f3
        );
