    min-width:34px;
    height:34px;
    padding:0 6px;
    border-radius:50% 50% 50% 8px;
    transform:rotate(-45deg);
    display:grid;
    place-items:center;
    border:2px solid #fff;
    box-shadow:0 4px 12px rgba(0,0,0,.30);
    color:#fff;
    font-size:8px;
    font-weight:900;
