/* Harmonized form-print rules: active only while printing E-Forms. */
@media print {

    body.form-printing html,
    body.form-printing {
        margin: 0 !important;
        padding: 0 !important;
        background: #ffffff !important;
    }

    body.form-printing .sidebar,
    body.form-printing .topbar,
    body.form-printing .safety-banner,
    body.form-printing .form-picker,
    body.form-printing .panel-head,
    body.form-printing .test-mode-ribbon,
    body.form-printing .command-hero,
    body.form-printing nav,
    body.form-printing header,
    body.form-printing footer,
    body.form-printing button {
        display: none !important;
    }

    body.form-printing .view {
        display: none !important;
    }

    body.form-printing #view-forms,
    body.form-printing #view-forms .form-workspace,
    body.form-printing #view-forms .form-canvas {
        display: block !important;
        width: 100% !important;
        height: auto !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        box-shadow: none !important;
        background: #ffffff !important;
        overflow: visible !important;
    }

    body.form-printing #view-forms .paper {
        display: block !important;
        margin: 0 auto !important;
        padding: 5mm !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        page-break-before: avoid !important;
        page-break-after: avoid !important;
        page-break-inside: avoid !important;
        break-before: avoid !important;
        break-after: avoid !important;
        break-inside: avoid !important;
        overflow: visible !important;
        background: #ffffff !important;
        transform-origin: top left !important;
    }

    body.form-printing #view-forms .table-wrap,
    body.form-printing #view-forms .hourly-matrix-wrap,
    body.form-printing #view-forms .feeder-load-wrap,
    body.form-printing #view-forms .condition-wrap {
        overflow: visible !important;
        max-height: none !important;
        width: auto !important;
        border: 0 !important;
    }

    body.form-printing #view-forms table,
    body.form-printing #view-forms tr,
    body.form-printing #view-forms td,
    body.form-printing #view-forms th {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }

    body.form-printing #view-forms input,
    body.form-printing #view-forms select,
    body.form-printing #view-forms textarea {
        color: #000 !important;
        background: transparent !important;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    body.form-printing #view-forms * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
}


